#include "ark/agent.hpp"
#include "ark/design_containers.hpp"
#include "ark/serialize.hpp"
#include "ark/iteration_history.hpp"
#include <filesystem>
#include <iostream>
#include <stdexcept>

namespace {
using namespace ark;
using V=arkjson::Value;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
V json(const char* text){V result;check(arkjson::parse(text,result),"Bad fixture JSON");return result;}
V data(const V& result){const auto* error=result.find("isError");if(error&&error->b)throw std::runtime_error(result.find("structuredContent")->dump());return *result.find("structuredContent");}
V apply(AgentSession& session,const char* text){V args=V::makeObj();args.set("commands",json(text));args.set("expected_revision",V::makeNum((double)session.revision));return data(session.call("doc_apply",args));}
V request(AgentSession& session,const char* action,const char* node=nullptr){V args=V::makeObj();args.set("action",V::makeStr(action));args.set("expected_revision",V::makeNum((double)session.revision));if(node)args.set("node",V::makeStr(node));return args;}
V checkout(AgentSession& session,const char* node="Scope"){return data(session.call("design_containers",request(session,"checkout",node)));}
AgentSession child(const V& checkout){AgentSession result;std::string error;check(documentFromJson(checkout.find("document")->dump(),result.document,&error),error.c_str());return result;}
bool has(const V& array,const std::string& value){for(const auto& row:array.arr)if(row.asStr()==value)return true;return false;}
std::string authoring(const Document& doc){return documentToJson(doc,false,false);}
void rejectTool(AgentSession& session,const char* tool,V args,const char* code){const auto before=authoring(session.document);const auto revision=session.revision;const auto response=session.call(tool,args);check(response.find("isError")->b,"Expected explicit rejection");const auto evidence=response.find("structuredContent")->dump();if(evidence.find(code)==std::string::npos)throw std::runtime_error(std::string("Expected ")+code+" from "+tool+", received "+evidence);check(session.revision==revision&&authoring(session.document)==before,"Rejection must preserve authored source and revision");}
void basic(AgentSession& s){apply(s,R"([{"op":"param.set","name":"shared","expr":"20"},{"op":"param.set","name":"local","expr":"8"},{"op":"feature.add","type":"box","name":"Outside","p":{"dx":"shared","dy":5,"dz":4}},{"op":"feature.add","type":"box","name":"Inside","p":{"dx":"shared","dy":"local","dz":3}},{"op":"assembly.add","name":"Scope","feature":0},{"op":"assembly.add","name":"Scoped occurrence","feature":"Inside","parent":"Scope"},{"op":"assembly.add","name":"Outside occurrence","feature":"Outside","p":{"tx":100}}])");}
V merge(AgentSession& source,const AgentSession& edited,bool preview=false){V args=request(source,"merge");V root;check(arkjson::parse(authoring(edited.document),root),"Bad child source");args.set("document",root);args.set("preview",V::makeBool(preview));return args;}

void scopedMerge(){
    AgentSession s;basic(s);const auto sourceBefore=authoring(s.document);const auto revision=s.revision;const auto exported=checkout(s);check(s.revision==revision&&authoring(s.document)==sourceBefore,"Checkout must not edit source authoring");auto c=child(exported);
    check(c.document.features.size()==1&&c.document.features[0].id==s.document.features[1].id,"Checkout must export scoped definitions with stable IDs");check(c.document.assembly.size()==2,"Checkout must omit outside occurrences");check(c.document.drawings.empty()&&c.document.usage.entries.empty()&&!c.document.agentActivity&&c.document.iterationHistory.isNull(),"Checkout cannot share audit/history or create drawings");
    const auto* manifest=exported.find("manifest");check(has(*manifest->find("readonly"),"params:shared"),"Shared parameter must be readonly");check(has(*manifest->find("editable"),"params:local"),"Exclusive parameter must remain editable");
    const auto* outside=s.document.find(1);const auto outsideName=outside->name,outsideDx=outside->get("dx");apply(c,R"([{"op":"param.set","name":"local","expr":"11"},{"op":"feature.edit","id":"Inside","p":{"dz":7}},{"op":"assembly.edit","id":"Scoped occurrence","p":{"tx":12}}])");const auto proposal=data(s.call("design_containers",merge(s,c,true)));check(s.revision==revision&&proposal.find("commands")->arr.size()==3,"Read-only proposal must retain bounded edits without publishing");data(s.call("design_containers",merge(s,c)));check(s.revision==revision+1,"Atomic merge must publish one revision");check(s.document.find(2)->get("dz")=="7"&&s.document.getParam("local")==11,"Merge must retain editable feature and parameter changes");check(s.document.find(1)->name==outsideName&&s.document.find(1)->get("dx")==outsideDx,"Merge must preserve outside authored feature");check(s.document.assembly[1].id==2&&s.document.assembly[1].p.at("tx")=="12","Merge must retain occurrence identity");check(s.document.designContainerCheckout.isNull()&&s.document.drawings.empty(),"Merge cannot attach a child manifest or create drawings in parent");
    auto replay=merge(s,c);rejectTool(s,"design_containers",replay,"CONTAINER_REVISION_CONFLICT");
}
void recipeOrdering(){
    AgentSession s;basic(s);apply(s,R"([{"op":"assembly.edit","id":"Scoped occurrence","pattern":{"type":"linear","count":3,"dx":10}}])");auto c=child(checkout(s));apply(c,R"([{"op":"assembly.add","name":"New driver","parent":"Scope","feature":"Inside","pattern":{"type":"linear","count":3,"dx":17}},{"op":"assembly.edit","id":"Scoped occurrence","pattern":{"type":"pattern_driven","source":{"node":"New driver"}}}])");data(s.call("design_containers",merge(s,c)));check(s.document.assembly[1].pattern.type=="pattern_driven"&&s.document.assembly.back().name=="New driver","Existing pattern must rebind after its new driver is created");check(s.document.assembly[1].pattern.source.find("node")->num==(double)s.document.assembly.back().id,"Dependency ordering must preserve the declared stable node mapping");
    AgentSession invalid;basic(invalid);auto bad=child(checkout(invalid));bad.document.find(2)->p["dz"]="0";rejectTool(invalid,"design_containers",merge(invalid,bad),"must be positive");
}
void boundaries(){
    AgentSession s;basic(s);auto c=child(checkout(s));V edit=V::makeObj();edit.set("expected_revision",V::makeNum((double)c.revision));edit.set("commands",json(R"([{"op":"param.set","name":"shared","expr":"99"}])"));rejectTool(c,"doc_apply",edit,"CONTAINER_READONLY_DEPENDENCY");
    edit.set("commands",json(R"([{"op":"assembly.edit","id":"Scoped occurrence","parent":0}])"));rejectTool(c,"doc_apply",edit,"CONTAINER_NODE_BOUNDARY");
    const auto observed=s.revision;apply(s,R"([{"op":"feature.edit","id":"Outside","p":{"dy":9}}])");rejectTool(s,"design_containers",merge(s,c),"CONTAINER_REVISION_CONFLICT");
    V stale=request(s,"checkout","Scope");stale.set("expected_revision",V::makeNum((double)observed));rejectTool(s,"design_containers",stale,"REVISION_CONFLICT");
    V missing=request(s,"checkout","Missing");rejectTool(s,"design_containers",missing,"CONTAINER_MISSING");V invalid=request(s,"checkout","Scoped occurrence");rejectTool(s,"design_containers",invalid,"CONTAINER_NOT_GROUP");
    auto f=child(checkout(s));apply(f,R"([{"op":"feature.edit","id":"Inside","p":{"dz":8}}])");s.document.find(1)->p["dy"]="17";rejectTool(s,"design_containers",merge(s,f),"CONTAINER_SOURCE_CONFLICT");
    AgentSession reviewed;basic(reviewed);auto changing=child(checkout(reviewed));apply(changing,R"([{"op":"feature.edit","id":"Inside","p":{"dz":8}}])");const auto proposal=data(reviewed.call("design_containers",merge(reviewed,changing,true)));apply(changing,R"([{"op":"feature.edit","id":"Inside","p":{"dz":9}}])");V approved=merge(reviewed,changing);approved.set("expected_child_sha256",*proposal.find("child_sha256"));rejectTool(reviewed,"design_containers",approved,"CONTAINER_CHILD_CONFLICT");
}
void dependencyClosure(){
    AgentSession s;apply(s,R"([{"op":"param.set","name":"height","expr":"3"},{"op":"plane.set","name":"Raised","parent":"XY","p":{"oz":"height"}},{"op":"sketch.set","name":"Profile","sketch":{"plane":"Raised","entities":[{"kind":"line","name":"rail","dof":[0,0,10,0]}]}},{"op":"feature.add","type":"box","name":"Dependency","p":{"dx":4,"dy":4,"dz":"height"}},{"op":"feature.add","type":"transform","name":"Inside","inputs":["Dependency"],"p":{"tx":6}},{"op":"feature.add","type":"box","name":"Outside","p":{"dx":2,"dy":2,"dz":2}},{"op":"assembly.add","name":"Scope","feature":0},{"op":"assembly.add","name":"Scoped occurrence","feature":"Inside","parent":"Scope"},{"op":"assembly.add","name":"Outside occurrence","feature":"Outside"}])");
    auto exported=checkout(s);auto c=child(exported);check(c.document.features.size()==2&&c.document.features[0].name=="Dependency","Feature input dependency closure must be exported in history order");check(c.document.sketches.empty()&&c.document.planes.empty(),"Unrelated source sketches and planes must remain outside");check(has(*exported.find("manifest")->find("readonly"),"features:1"),"External input definition is explicitly readonly");c.document.recompute();check(c.document.lastResults.size()==2,"Child recomputes the actual subset and dependency closure");V edit=V::makeObj();edit.set("expected_revision",V::makeNum((double)c.revision));edit.set("commands",json(R"([{"op":"feature.edit","id":"Dependency","p":{"dx":5}}])"));rejectTool(c,"doc_apply",edit,"CONTAINER_READONLY_DEPENDENCY");
    AgentSession sketches;apply(sketches,R"([{"op":"param.set","name":"height","expr":"3"},{"op":"plane.set","name":"Raised","parent":"XY","p":{"oz":"height"}},{"op":"sketch.set","name":"Profile","sketch":{"plane":"Raised","entities":[{"kind":"circle","name":"rim","dof":[0,0,2]}],"constraints":[{"type":"radius","a":0,"b":-1,"val":2}]}},{"op":"feature.add","type":"extrude","name":"Inside","p":{"sketch":"Profile","height":5}},{"op":"assembly.add","name":"Scope","feature":0},{"op":"assembly.add","name":"Scoped occurrence","feature":"Inside","parent":"Scope"}])");auto sketchChild=child(checkout(sketches));check(sketchChild.document.sketches.size()==1&&sketchChild.document.planes.size()==1&&sketchChild.document.params.size()==1,"Named sketch/plane/expression closure must be complete");apply(sketchChild,R"([{"op":"param.set","name":"height","expr":"7"}])");data(sketches.call("design_containers",merge(sketches,sketchChild)));check(sketches.document.getParam("height")==7,"Exclusive sketch/datum source remains editable");
    apply(sketches,R"([{"op":"plane.set","name":"Raised","support":{"kind":"offset_plane","plane":"XY","offset":2}}])");auto support=child(checkout(sketches));apply(support,R"([{"op":"plane.set","name":"Raised","support":null}])");data(sketches.call("design_containers",merge(sketches,support)));check(sketches.document.planes[0].support.isNull(),"An explicitly cleared datum support must not silently retain the old source recipe");
}
void identitiesAndNamespaces(){
    AgentSession s;basic(s);auto c=child(checkout(s));apply(c,R"([{"op":"feature.add","type":"box","name":"New scoped part","p":{"dx":1,"dy":2,"dz":3}},{"op":"assembly.add","name":"New scoped occurrence","feature":"New scoped part","parent":"Scope"}])");const auto originalNew=c.document.features.back().id;data(s.call("design_containers",merge(s,c)));check(s.document.features.back().id==originalNew&&s.document.assembly.back().feature==originalNew,"New definition/occurrence IDs must map coherently into parent counters");
    auto collision=child(checkout(s));apply(collision,R"([{"op":"feature.add","type":"box","name":"Outside","p":{"dx":1,"dy":1,"dz":1}}])");rejectTool(s,"design_containers",merge(s,collision),"CONTAINER_NAMESPACE_CONFLICT");
    auto tampered=child(checkout(s));tampered.document.designContainerCheckout.set("source_sha256",V::makeStr(std::string(64,'0')));rejectTool(s,"design_containers",merge(s,tampered),"CONTAINER_SOURCE_CONFLICT");
    std::string error;auto invalid=tampered.document.designContainerCheckout;invalid.set("baseline_sha256",V::makeStr(std::string(64,'0')));check(!validateDesignContainerManifest(invalid,error),"Malformed retained baseline must reject during persistence load");
    AgentSession keys;basic(keys);apply(keys,R"([{"op":"feature.edit","id":"Inside","p":{"density":7.85}}])");auto removed=child(checkout(keys));apply(removed,R"([{"op":"feature.edit","id":"Inside","p_remove":["density"]}])");data(keys.call("design_containers",merge(keys,removed)));check(!keys.document.find(2)->p.count("density"),"Explicit feature parameter removal must survive atomic merge");
}
void crossBoundaryRelations(){
    AgentSession shared;basic(shared);apply(shared,R"([{"op":"assembly.add","name":"Reused outside","feature":"Inside"}])");rejectTool(shared,"design_containers",request(shared,"checkout","Scope"),"CONTAINER_SHARED_DEFINITION");
    AgentSession consumer;basic(consumer);apply(consumer,R"([{"op":"feature.add","type":"transform","name":"Outside consumer","inputs":["Inside"],"p":{"tx":10}}])");rejectTool(consumer,"design_containers",request(consumer,"checkout","Scope"),"CONTAINER_EXTERNAL_CONSUMER");
    AgentSession mate;basic(mate);AssemblyMate relation;relation.id=mate.document.nextMateId_++;relation.a=2;relation.b=3;relation.type="rigid";mate.document.mates.push_back(relation);rejectTool(mate,"design_containers",request(mate,"checkout","Scope"),"CONTAINER_CROSS_BOUNDARY_MATE");
    AgentSession ancestor;apply(ancestor,R"([{"op":"param.set","name":"placement","expr":"15"},{"op":"feature.add","type":"box","name":"Inside","p":{"dx":2,"dy":2,"dz":2}},{"op":"assembly.add","name":"Parent","feature":0,"p":{"tx":"placement"}},{"op":"assembly.add","name":"Scope","feature":0,"parent":"Parent","p":{"ty":8}},{"op":"assembly.add","name":"Scoped occurrence","feature":"Inside","parent":"Scope"}])");const auto exported=checkout(ancestor);auto c=child(exported);check(c.document.assembly.size()==3&&has(*exported.find("manifest")->find("readonly"),"assembly:1"),"Exact parent frames remain readonly source closure");std::vector<AssemblyPlacement> original,scoped;std::string error;check(resolveAssembly(ancestor.document,original,error)&&resolveAssembly(c.document,scoped,error),"Ancestor scope must resolve");check(original[0].world.transformPoint({}).x==scoped[0].world.transformPoint({}).x&&original[0].world.transformPoint({}).y==scoped[0].world.transformPoint({}).y,"Checkout must preserve authored ancestor world pose");
}
void persistenceAndPaths(){
    AgentSession s;basic(s);const auto token=iterationSha256(std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())).substr(0,16);const auto folder=std::filesystem::temp_directory_path()/("ark-container-tests-"+token);std::filesystem::create_directory(folder);const auto path=folder/"child.ark";auto args=request(s,"checkout","Scope");args.set("path",V::makeStr(path.string()));data(s.call("design_containers",args));Document loaded;std::string error;check(loadDocument(path.string().c_str(),loaded,&error),error.c_str());check(loaded.designContainerCheckout.t==V::Obj,"Binary save/load must retain container provenance");check(loaded.drawings.empty(),"Persistence must not create drawing source");const auto original=authoring(loaded);rejectTool(s,"design_containers",args,"CONTAINER_PATH_EXISTS");Document preserved;check(loadDocument(path.string().c_str(),preserved,&error)&&authoring(preserved)==original,"Repeated checkout must not overwrite the existing child project");std::filesystem::remove(path);std::filesystem::remove(folder);
    auto c=child(checkout(s));const auto manifest=c.document.designContainerCheckout;apply(c,R"([{"op":"feature.edit","id":"Inside","p":{"dz":9}}])");data(c.call("doc_undo",V::makeObj()));const auto& restored=c.document.designContainerCheckout;check(restored.t==V::Obj&&restored.find("baseline_sha256")->str==manifest.find("baseline_sha256")->str&&restored.find("source_sha256")->str==manifest.find("source_sha256")->str&&restored.find("editable")->dump()==manifest.find("editable")->dump()&&restored.find("readonly")->dump()==manifest.find("readonly")->dump(),"Undo must retain checkout baseline and ownership");check(validateDesignContainerManifest(restored,error),"Undo manifest must remain valid");
}
}
int main(){try{scopedMerge();recipeOrdering();boundaries();dependencyClosure();identitiesAndNamespaces();crossBoundaryRelations();persistenceAndPaths();std::cout<<"Design container contracts passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
